PL-2.0#!/bin/env bash ## Author: SuperManito ## Modified: 2021-5-25 ## License: GPL-2.0 ## Repository: https://github.com/SuperManito/LinuxMirrors ## https://gitee.com/SuperManito/LinuxMirrors function AuthorAutograph() { echo &#39; __ ___ __ ____ / |/ /___ _____/ /__ / __ )__ __ / /|_/ / __ `/ __ / _ \ / __ / / / / / / / / /_/ / /_/ / __/ / /_/ / /_/ / /_/ /_/\__,_/\__,_/\___/ /_____/\__, / /____/ _____ __ ___ _ __ / ___/__ ______ ___ _____/ |/ /___ _____ (_) /_____ \__ / / / / __ / _ / ___/ /|_/ / __ `/ __ / / __/ __ \ ___/ / /_/ / /_/ / __/ / / / / / /_/ / / / / / /_/ /_/ / /____/\__,_/ .___/\___/_/ /_/ /_/\__,_/_/ /_/_/\__/\____/ /_/ &#39; } ## 定义目录和文件 RedHatRelease=/etc/redhat-release DebianSourceList=/etc/apt/sources.list DebianSourceListBackup=/etc/apt/sources.list.bak DebianExtendListDirectory=/etc/apt/sources.list.d DebianExtendListDirectoryBackup=/etc/apt/sources.list.d.bak RedHatReposDirectory=/etc/yum.repos.d RedHatReposDirectoryBackup=/etc/yum.repos.d.bak ## 定义系统变量 DebianRelease=lsb_release Architecture=$(uname -m) SYSTEM_DEBIAN=Debian SYSTEM_UBUNTU=Ubuntu SYSTEM_KALI=Kali SYSTEM_REDHAT=RedHat SYSTEM_CENTOS=CentOS SYSTEM_FEDORA=Fedora ## 定义 Docker 相关变量 DockerSourceList=${DebianExtendListDirectory}/docker.list DockerRepo=${RedHatReposDirectory}/docker-ce.repo DockerDirectory=/etc/docker DockerConfig=${DockerDirectory}/daemon.json DockerConfigBackup=${DockerDirectory}/daemon.json.bak DockerCompose=/usr/local/bin/docker-compose PROXY_URL=https://ghproxy.com/ DOCKER_COMPOSE_VERSION=1.29.2 DOCKER_COMPOSE_URL=https://github.com/docker/compose/releases/download/${DOCKER_COMPOSE_VERSION}/docker-compose-Linux-x86_64 ## 组合各个函数模块 function CombinationFunction() { PermissionJudgment &amp;&amp; NetWorkJudgment &amp;&amp; clear EnvJudgment TurnOffFirewall ChooseMirrors RemoveOldVersion DockerEngine [ ${DOCKER_COMPOSE} = &#34;True&#34; ] &amp;&amp; DockerCompose ShowVersion AuthorAutograph } ## 系统判定变量 function EnvJudgment() { ## 判定当前系统基于 Debian or RedHat if [ -f ${RedHatRelease} ]; then SYSTEM=${SYSTEM_REDHAT} else SYSTEM=${SYSTEM_DEBIAN} fi ## 判定系统名称、版本、版本号 if [ ${SYSTEM} = ${SYSTEM_DEBIAN} ]; then SYSTEM_NAME=$(${DebianRelease} -is) SYSTEM_VERSION=$(${DebianRelease} -cs) SYSTEM_VERSION_NUMBER=$(${DebianRelease} -rs) elif [ ${SYSTEM} = ${SYSTEM_REDHAT} ]; then SYSTEM_NAME=$(cat ${RedHatRelease} | cut -c1-6) if [ ${SYSTEM_NAME} = ${SYSTEM_CENTOS} ]; then SYSTEM_VERSION_NUMBER=$(cat ${RedHatRelease} | cut -c22-24) CENTOS_VERSION=$(cat ${RedHatRelease} | cut -c22) elif [ ${SYSTEM_NAME} = ${SYSTEM_FEDORA} ]; then SYSTEM_VERSION_NUMBER=$(cat ${RedHatRelease} | cut -c16-18) fi fi ## 判定系统处理器架构 if [ ${Architecture} = &#34;x86_64&#34; ]; then SYSTEM_ARCH=x86_64 SOURCE_ARCH=amd64 elif [ ${Architecture} = &#34;aarch64&#34; ]; then SYSTEM_ARCH=arm64 SOURCE_ARCH=arm64 elif [ ${Architecture} = &#34;armv7l&#34; ]; then SYSTEM_ARCH=armv7 SOURCE_ARCH=armhf elif [ ${Architecture} = &#34;armv*&#34; ]; then SYSTEM_ARCH=${Architecture} SOURCE_ARCH=armhf elif [ ${Architecture} = &#34;i686&#34; ]; then SYSTEM_ARCH=x86_32 echo -e &#39;
